head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.procJob = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.pUsrTpCd = js_usr_tp_cd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 담당자 버튼
        btn_TrSend.setDisabled(true);

        // 마감일
        const vCurDate = $c.ut.cGetToday("yyyymmdd");
        edt_TASK_DD.setValue(vCurDate);
        MaxTab_01.setSelectedTabIndex(1);
        $c.cm.PanelToGroupBox(panel_Top);

        // 조회
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MaxTab_01_OnSelChanged
 * @description Max Tab 01 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MaxTab_01_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === "1") {
            edt_TASK_DD.setReadOnly(true);
            img_TASK_DD.setDisabled(true);
            edt_TASK_DD.ReadOnlyBackColor = "#b9d4f7";
            edt_TASK_DD.setValue($c.ut.cGetToday("yyyymmdd"));
        } else if (nIndex === "2") {
            edt_TASK_DD.setReadOnly(false);
            img_TASK_DD.setDisabled(false);
        }
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.MaxTab_01_OnSelChanged" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09330.btn_Search_onclick" });
    }
};

