///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 사용자구분코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let url;

    // 이후 영업 상장일
    url += "&TASK_DD=" + edt_TASK_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Get_ListDD",
        action : "/ElwListedReceive.do",
        ref : "",
        target : "dts_Get_ListDD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 마감정보
    url += "?SCREN_ID=" + "ULDSTF09330.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=selectManagement&inputMessageId=PF_CLSBZ_LOG_INOUT";
    url += "&DIV_IDX=" + DIV_R_LISTING_PF_CLSBZ; // 2
    url += "&TASK_DD=" + edt_TASK_DD.getValue();
    const sbmOptions2 = {
        id : "sbm_dts_Item",
        action : "/pf/PfLstinvstg.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 마감처리
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        // 신규상장
        url += "?SCREN_ID=" + "ULDSTF09330.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=selectManagement&inputMessageId=PF_NEWLISTING_INOUT";
        url += "&DIV_IDX=" + DIV_L_LISTING_PF_DETAIL; // 3
        url += "&LIST_DD=" + edt_LIST_DD.getValue();
        const sbmOptions = {
            id : "sbm_dts_New_Proc",
            action : "/pf/PfLstinvstg.do",
            ref : "",
            target : "dts_New_Proc=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

        // 마감처리내역

    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        // 마감처리내역
        url += "?SCREN_ID=" + "ULDSTF09330.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        url += "&method=selectManagement&inputMessageId=PF_NEWLISTING_INOUT";
        url += "&DIV_IDX=" + DIV_L_LISTING_PF_SEND; // 4
        url += "&TASK_DD=" + edt_TASK_DD.getValue();
        const sbmOptions = {
            id : "sbm_dts_New_Search",
            action : "/pf/PfLstinvstg.do",
            ref : "",
            target : "dts_New_Search=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
};

/**
 * @method
 * @name trSetHeader
 * @description tr Set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trSetHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cls",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Cls=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Cls.insertRow();
};

/**
 * @method
 * @name trsend
 * @description 마감처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trsend = async function() {
    scwin.procJob = "마감처리";
    res = window.confirm("[마감] 처리 하겠습니까?");
    if (res) {
        await scwin.trSetHeader();
        dts_Cls.setCellData(1, "TASK_DD", edt_TASK_DD.getValue());
        dts_Cls.setCellData(1, "LIST_DD", edt_LIST_DD.getValue());
        dts_Cls.setCellData(1, "APPROV_EMP_NO", js_emp_no);
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_INSERT,
        //     TASK_DD : $c.stf.getObjectValue(edt_TASK_DD)
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/pf/PfLstinvstg.do",
            ref : "dts_Cls",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

/**
 * @method
 * @name reTrsend
 * @description 재마감
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reTrsend = async function() {
    scwin.procJob = "재마감처리";
    let res = window.confirm("[재마감] 처리 하겠습니까?");
    if (res) {
        await scwin.trSetHeader();
        dts_Cls.setCellData(1, "TASK_DD", edt_TASK_DD.getValue());
        dts_Cls.setCellData(1, "LIST_DD", edt_LIST_DD.getValue());
        dts_Cls.setCellData(1, "APPROV_EMP_NO", js_emp_no);
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : TR_JOB_DELETE,
        //     TASK_DD : $c.stf.getObjectValue(edt_TASK_DD)
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/pf/PfLstinvstg.do",
            ref : "dts_Cls",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name buttonTrSend
 * @description Button
 * @returns {void}
 * @hidden N
 */
scwin.buttonTrSend = function() {
    // 마감 Button
    if (txb_BZ_CLS_TM.getValue() === "") {
        btn_TrSend.setDisabled(false);
        btn_TrSend.setBackgroundImage("../img/btn_ClsPrc.gif");
    } else {
        btn_TrSend.setDisabled(true);
        btn_TrSend.setBackgroundImage("../img/btn_ClsPrc_d.gif");
    }

    // 재마감 Button
    if (scwin.pUsrTpCd === "1") {
        // 운영자
        btn_ReTrSend.setDisabled(false);
        btn_ReTrSend.show("");
    } else {
        btn_ReTrSend.setDisabled(true);
        btn_ReTrSend.hide();
    }
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    if (MaxTab_01.getSelectedTabIndex() === 1) {
        $c.data.downloadGridViewExcel(grd_New_Proc, {fileName: "상장형 수익증권 신규상장 마감처리목록", type: "8"});
    } else if (MaxTab_01.getSelectedTabIndex() === 2) {
        $c.data.downloadGridViewExcel(grd_New_Search, {fileName: "상장형 수익증권 신규상장 송신목록", type: "8"});
    }
};
